import {CENTER,DEMO_POINTS,escapeHtml as e,canRoute,haversine,planOrder,routeParts,mapsURL,validCoordinate} from './core.mjs';
import {discover,weather,sights,getCache,CACHE_PREFIX} from './api.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={demo:true,ids:[],filter:'all',query:'',trust:'all',osm:[],sights:[],location:null,ordering:'manual',start:'center'};
try{const saved=JSON.parse(localStorage.getItem('alunue-refill-state-v1')||'null');if(saved){state.demo=typeof saved.demo==='boolean'?saved.demo:true;state.ids=Array.isArray(saved.ids)?saved.ids.filter(x=>typeof x==='string'):[];state.ordering=['manual','direct','discover'].includes(saved.ordering)?saved.ordering:'manual';}}catch{}
const cachedOSM=getCache('osm-evora'),cachedSights=getCache('sights-evora');state.osm=Array.isArray(cachedOSM?.data)?cachedOSM.data:[];state.sights=Array.isArray(cachedSights?.data)?cachedSights.data:[];
function all(){return [...(state.demo?DEMO_POINTS:[]),...state.osm,...state.sights];}
function save(){try{localStorage.setItem('alunue-refill-state-v1',JSON.stringify({demo:state.demo,ids:state.ids,ordering:state.ordering}));}catch{toast('Storage unavailable. This session still works; save an itinerary text copy.');}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6500);}
function origin(){if(state.start==='gps'){if(!state.location)throw Error('Use my location first, or choose a manual start.');return state.location;}if(state.start==='manual'){const p={lat:Number($('#lat').value),lon:Number($('#lon').value)};if($('#lat').value===''||$('#lon').value===''||!validCoordinate(p))throw Error('Enter valid latitude and longitude.');return p;}return state.start==='campus'?{lat:38.5684,lon:-7.9105}:CENTER;}
function selected(){return state.ids.map(id=>all().find(p=>p.id===id)).filter(Boolean);}
function readyStops(){return selected().filter(p=>canRoute(p,state.demo));}
function renderCards(){let points=all().filter(p=>(state.filter==='all'||p.kind===state.filter)&&p.name.toLowerCase().includes(state.query.toLowerCase())&&(state.trust!=='routeable'||canRoute(p,state.demo)));if(state.location)points.sort((a,b)=>haversine(state.location,a)-haversine(state.location,b));$('#inventory-note').textContent=`${state.osm.filter(p=>p.kind==='water').length} mapped water candidates · 0 independently verified real refill points. Cached candidates keep their unverified status.`;$('#cards').innerHTML=points.length?points.map(p=>{const added=state.ids.includes(p.id),allowed=canRoute(p,state.demo);return `<article class="place"><div class="card-top"><span class="place-type">${e(p.kind==='partner'?'Independent shop':p.kind)}</span><span class="badge ${p.demo||p.status==='candidate'?'warn':''}">${p.demo?'DEMO ONLY':p.status==='candidate'?'NEEDS CHECKING':'CULTURAL REFERENCE'}</span></div><h3>${e(p.name)}</h3><p>${e(p.opening||'Hours unknown')}</p><p>${p.demo?'A fictional service scenario for prototype testing.':p.kind==='water'?'Map data is not a current drinking-water, free-access or availability check.':p.kind==='grocery'?'No live price or opening guarantee. Search store names to narrow the list.':'An optional cultural stop. Access and opening hours need checking.'}</p>${state.location?`<p class="fine">${haversine(state.location,p).toFixed(2)} km away in a straight line; walking distance differs.</p>`:''}<details><summary>Source & trust details</summary><p>${e(p.sourceLabel)}<br>${e(p.access||'Access unknown')}<br>${p.checkedAt?`Checked ${e(p.checkedAt)}`:'No independent refill verification date'}</p>${p.source?`<a target="_blank" rel="noopener" href="${e(p.source)}">Inspect source ↗</a>`:''}</details><button data-add="${e(p.id)}" ${!allowed?'disabled':''}>${added?'Remove from journey':!allowed?'Verification needed before routing':'Add to journey +'}</button></article>`;}).join(''):'<div class="empty"><h3>No places match yet.</h3><p>Try another filter, turn on the demo, or load map candidates. A missing inventory is shown as missing.</p></div>';$$('[data-add]').forEach(b=>b.onclick=()=>{const id=b.dataset.add;state.ids=state.ids.includes(id)?state.ids.filter(x=>x!==id):[...state.ids,id];save();render();});}
function ordered(){return planOrder(origin(),readyStops(),state.ordering);}
function itinerary(){const stops=ordered();if(!stops.length)return 'No stops selected.';return ['AlunUÉ Refill itinerary',stops.some(p=>p.demo)?'DEMO SCENARIO: fictional refills; do not rely on them for water.':'Check access and opening before setting out.',`Start: ${origin().lat}, ${origin().lon}`,...stops.map((p,i)=>`${i+1}. ${p.name} (${p.lat}, ${p.lon})${p.demo?' [DEMO]':''}`),...routeParts(origin(),stops).map((p,i)=>`Google Maps part ${i+1}: ${p.url}`),'Ordering is heuristic, not optimal street routing.'].join('\n');}
function renderJourney(){const list=selected();$('#count').textContent=String(list.length);$('#stops').innerHTML=list.length?list.map((p,i)=>`<li><b>${e(p.name)}</b> <span class="badge">${p.demo?'DEMO':e(p.status)}</span><br><button data-up="${i}" ${i===0?'disabled':''} aria-label="Move ${e(p.name)} earlier">↑ Earlier</button><button data-down="${i}" ${i===list.length-1?'disabled':''} aria-label="Move ${e(p.name)} later">↓ Later</button><button data-remove="${e(p.id)}">Remove</button></li>`).join(''):'<p>No stops yet. Add a demonstration stop, a grocery or a cultural reference from Discover.</p>';$$('[data-remove]').forEach(b=>b.onclick=()=>{state.ids=state.ids.filter(id=>id!==b.dataset.remove);save();render();});for(const [attr,delta] of [['up',-1],['down',1]])$$(`[data-${attr}]`).forEach(b=>b.onclick=()=>{state.ordering='manual';$('#ordering').value='manual';const idx=Number(b.dataset[attr]);const ids=list.map(p=>p.id);[ids[idx],ids[idx+delta]]=[ids[idx+delta],ids[idx]];state.ids=ids;save();render();});try{const stops=ordered();$('#route-summary').textContent=stops.length?`${stops.length} eligible stop(s). ${stops.some(p=>p.demo)?'Contains fictional demo locations. ':''}${state.ordering==='manual'?'Export keeps your chosen order.':'Suggested export order: '+stops.map(p=>p.name).join(' → ')} A street route is calculated by Google Maps.`:'';$('#exports').innerHTML=stops.length?routeParts(origin(),stops).map((p,i)=>`<a class="button primary" target="_blank" rel="noopener" href="${e(p.url)}">Open walking directions${stops.length>4?` · part ${i+1}`:''} ↗</a>`).join('')+`<details><summary>Individual walking legs · fallback</summary>${stops.map((p,i)=>`<a target="_blank" rel="noopener" href="${e(mapsURL(i===0?origin():stops[i-1],[p]))}">Leg ${i+1}: ${e(p.name)} ↗</a>`).join('')}</details>`:'';}catch(error){$('#route-summary').textContent=error.message;$('#exports').innerHTML='';}}
function render(){renderCards();renderJourney();$('#demo-toggle').textContent=state.demo?'Demo scenario is on':'Demo scenario is off';$('#demo-toggle').setAttribute('aria-pressed',String(state.demo));$('#mode-notice').innerHTML=state.demo?'<b>Explore a demonstration.</b> Refill and shop pins are synthetic scenarios, not real places to obtain water. Live map candidates need verification.':'<b>Live discovery mode.</b> No independently verified free refill points are available in this prototype. Map candidates remain unverified; groceries and sights may be added as optional stops.';}
function navigate(){const key=location.hash.slice(1)||'discover',valid=['discover','journey','community','project'].includes(key)?key:'discover';$$('.view').forEach(v=>v.hidden=v.id!==valid);$$('[data-tab]').forEach(a=>{if(a.dataset.tab===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${valid==='discover'?'Discover':valid==='journey'?'My journey':valid==='community'?'Refill community':'The project'} · AlunUÉ Refill`;}
addEventListener('hashchange',navigate);
$('#search').oninput=x=>{state.query=x.target.value;renderCards();};$('#trust').onchange=x=>{state.trust=x.target.value;renderCards();};$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderCards();});
$('#demo-toggle').onclick=()=>{state.demo=!state.demo;state.ids=state.ids.filter(id=>!id.startsWith('demo-'));save();render();};
$('#locate').onclick=()=>{if(!navigator.geolocation){toast('Location is not supported. Choose a start on My journey.');return;}$('#locate').disabled=true;navigator.geolocation.getCurrentPosition(pos=>{state.location={lat:pos.coords.latitude,lon:pos.coords.longitude};$('#locate').disabled=false;toast('Location set for this session. Distances are straight-line estimates.');render();},()=>{$('#locate').disabled=false;toast('Location unavailable. Choose Évora centre, CLV or manual coordinates.');},{enableHighAccuracy:false,timeout:10000,maximumAge:60000});};
$('#start').onchange=x=>{state.start=x.target.value;$('#manual').hidden=state.start!=='manual';renderJourney();};$('#ordering').value=state.ordering;$('#ordering').onchange=x=>{state.ordering=x.target.value;save();renderJourney();};for(const sel of ['#lat','#lon'])$(sel).oninput=renderJourney;$('#clear').onclick=()=>{state.ids=[];save();render();};
async function load(button,fn,apply){button.disabled=true;$('#api-status').textContent='Connecting… please wait.';try{const result=await fn();apply(result.data);$('#api-status').textContent=`${result.stale?'Service unavailable · showing stale saved data':result.cached?'Using a saved snapshot':'Loaded a fresh snapshot'} · ${new Date(result.at).toLocaleString('en-GB',{timeZone:'Europe/Lisbon'})} Lisbon. ${result.error||''}`;render();}catch(error){$('#api-status').textContent=`Could not load: ${error.message} Your current list and itinerary remain available.`;}finally{button.disabled=false;}}
$('#load-osm').onclick=()=>load($('#load-osm'),()=>discover(false),data=>{state.osm=data;});$('#load-sights').onclick=()=>load($('#load-sights'),sights,data=>{state.sights=data;});$('#load-weather').onclick=()=>load($('#load-weather'),weather,data=>{$('#weather').textContent=`${data.temperature_2m}°C · feels like ${data.apparent_temperature??'unknown'}°C`;});
$('#copy').onclick=async()=>{try{const text=itinerary();if(!navigator.clipboard)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(text);toast('Itinerary copied.');}catch(error){toast('Copy unavailable. Use Save itinerary text.');}};$('#share').onclick=async()=>{try{const text=itinerary();if(!navigator.share){toast('Sharing unavailable. Copy or save the itinerary instead.');return;}await navigator.share({title:'AlunUÉ Refill journey',text});}catch(error){if(error.name!=='AbortError')toast('Sharing failed. Copy or save the itinerary instead.');}};$('#download').onclick=()=>{try{const blob=new Blob([itinerary()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='alunue-refill-itinerary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message);}};
$('#suggest').onsubmit=event=>{event.preventDefault();const form=event.target,values=new FormData(form);try{const old=JSON.parse(localStorage.getItem('alunue-refill-suggestions-v1')||'[]');old.push({place:values.get('place'),note:values.get('note'),at:new Date().toISOString(),status:'local-draft'});localStorage.setItem('alunue-refill-suggestions-v1',JSON.stringify(old));$('#suggest-status').textContent='Saved on this browser only. Nothing was submitted or verified.';form.reset();}catch{$('#suggest-status').textContent='Storage unavailable. Your draft remains in the form; copy it before leaving.';}};
$('#delete-local').onclick=()=>{try{Object.keys(localStorage).filter(k=>k.startsWith('alunue-refill-')||k.startsWith(CACHE_PREFIX)).forEach(k=>localStorage.removeItem(k));}catch{}state.ids=[];state.osm=[];state.sights=[];state.location=null;$('#weather').textContent='';$('#suggest').reset();$('#suggest-status').textContent='Saved application preferences, snapshots and suggestions cleared.';render();toast('Local application data cleared. Offline app-shell files are managed by your browser.');};
let installPrompt;addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('#install').hidden=false;});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}};
function networkState(){if(!navigator.onLine)toast('Offline: use saved data and itinerary text. External maps and live services need a connection.');}addEventListener('offline',networkState);addEventListener('online',()=>toast('Connection restored. Live requests run only when you choose them.'));
if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').then(()=>{$('#offline-state').textContent='Offline app-shell caching is registered. Complete one online visit and reopen to check support on your phone. API snapshots are stored only after a successful request. External maps need connectivity.';}).catch(()=>{$('#offline-state').textContent='Offline caching is unavailable in this browser or hosting context. Save an itinerary text copy.';});
render();navigate();networkState();
